interface.signature:
interface RetentionCurve {
  videoId: string;
  points: Array<{
    percentage: number; // 0-100 (video progress)
    retention: number;  // 0-100 (% viewers remaining)
  }>;
  dropOffPoints: Array<{
    percentage: number;
    dropAmount: number;
    severity: 'low' | 'medium' | 'high';
  }>;
}
